#!/usr/bin/env python3
"""Build the ``oakd_pro`` device model in ``roqsim_sensors/models/oakd_pro/`` from the vendor link.

    python external/convert/build_oakd_pro.py                          # the model
    python external/convert/build_oakd_pro.py --mount-delta            # print the pose delta
    python external/convert/build_oakd_pro.py --rewrite-mounts world.yaml [...]

Writes the MJCF ``oakd_pro.xml`` and the generated block of ``oakd_pro.manifest.yaml``
(``device_name:``, ``frame_id:`` and ``frames:``, between the two ``generated by`` marker lines; the
rest of the manifest is authored by hand). Every number is read from ``oakd.urdf.xacro`` in
``turtlebot4/turtlebot4`` at the commit the TurtleBot 4 model is pinned to, by evaluating the macro's
own ``xacro:property`` expressions. The macro reads ``cm2m`` from
``irobot_create_description/urdf/common_properties.urdf.xacro``, which is 0.01 there.

**The MJCF ``mount`` body is ``<name>_link``** (``oakd_link``), the link the macro attaches to its
parent and hangs every camera frame from:

* the box is the vendor collision box at its vendor offset; there is no mesh (the vendor's
  ``oakd_pro.dae`` is 12 MB), so the box is also what renders;
* the body carries the vendor ``<inertial>`` (0.061 kg and the xacro's tensor, at the link origin);
* ``oakd_rgb`` is the vendor ``<name>_rgb_camera_optical_frame``, turned into MuJoCo's camera
  convention (looks down ``-z``, ``+y`` up); its ``fovy`` is the Gazebo block's ``horizontal_fov``
  re-expressed vertically at the block's own resolution;
* the front glass plate is a display cue on the box's front face, not a vendor part.

The manifest's ``frames:`` chain is the macro's: the RGB, left and right camera frames with their
optical frames, and the IMU frame.

**Re-expressing a mount.** The retired ``oakd`` model pre-rotated ``mount`` by
:data:`RETIRED_MOUNT_QUAT` (+90 deg about z) so a mount at ``rpy [0, 0, 0]`` looked along ``+y``, with
every geom already in ``oakd_link``. A mount of the old model at ``T_old`` becomes ``T_old * D`` with
``D = Rq``; ``--rewrite-mounts`` applies it (``vendor_mount.py``).
"""

from __future__ import annotations

import argparse
import math
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent))
from sources import resolve_source  # noqa: E402
from vendor_mount import (  # noqa: E402
    Xacro,
    fmt_list,
    fmt_num,
    fmt_vec,
    matrix_rpy,
    quat_matrix,
    rewrite_mounts,
    rpy_matrix,
    splice,
)

ROOT = Path(__file__).resolve().parents[2]
MODEL = ROOT / "roqsim_sensors/src/roqsim_sensors/models/oakd_pro"

TURTLEBOT4_URL = "https://github.com/turtlebot/turtlebot4.git"
#: `jazzy`, tag 2.1.1 -- the pin build_scanner_devices.py and the TurtleBot 4 model use.
TURTLEBOT4_COMMIT = "7fd29fb420e906f3aca4a904adb54b69b11c7c00"
XACRO = "turtlebot4_description/urdf/sensors/oakd.urdf.xacro"
#: irobot_create_description/urdf/common_properties.urdf.xacro, which the macro includes.
CM2M = 0.01

#: The retired ``oakd`` model's ``mount`` quaternion (w, x, y, z): +90 deg about z.
RETIRED_MOUNT_QUAT = (0.70710678, 0.0, 0.0, 0.70710678)

BEGIN = "# --- generated by external/convert/build_oakd_pro.py from turtlebot4_description"
END = "# --- end of generated block"


def vendor(source: Path | None = None) -> dict:
    """What the model is built from, all in ``oakd_link``."""
    source = source or resolve_source("turtlebot4", TURTLEBOT4_URL, TURTLEBOT4_COMMIT)
    x = Xacro(source / XACRO, "oakd", {"cm2m": CM2M})
    v = x.values
    link = next(el for el in x.root.iter("link") if el.get("name") == "${base_frame}")
    inertia = link.find("inertial/inertia")
    tensor = {k: float(inertia.get(k)) for k in ("ixx", "iyy", "izz", "ixy", "ixz", "iyz")}
    if any(tensor[k] for k in ("ixy", "ixz", "iyz")):
        raise RuntimeError(f"{XACRO}: the OAK-D inertia is no longer diagonal")
    rgb, rgb_rpy, _ = x.joint("rgb_camera_joint")
    _, optical, _ = x.joint("rgb_camera_optical_joint")
    left, left_rpy, _ = x.joint("left_camera_joint")
    right, right_rpy, _ = x.joint("right_camera_joint")
    _, left_optical, _ = x.joint("left_camera_optical_joint")
    _, right_optical, _ = x.joint("right_camera_optical_joint")
    imu, imu_rpy, _ = x.joint("imu_joint")
    if any(rgb_rpy) or any(left_rpy) or any(right_rpy):
        raise RuntimeError(f"{XACRO}: a camera frame is rotated from oakd_link")
    if not (np.allclose(left_optical, optical) and np.allclose(right_optical, optical)):
        raise RuntimeError(f"{XACRO}: the optical rotations differ between cameras")
    fov = x.root.find(".//gazebo/sensor/camera")
    hfov = float(fov.find("horizontal_fov").text)
    width, height = int(fov.find("image/width").text), int(fov.find("image/height").text)
    return {
        "mass": float(v["mass"]),
        "diaginertia": (tensor["ixx"], tensor["iyy"], tensor["izz"]),
        "box_size": (v["collision_length_x"], v["collision_length_y"], v["collision_length_z"]),
        "box_pos": (v["collision_offset_x"], v["collision_offset_y"], v["collision_offset_z"]),
        "rgb": rgb,
        "optical_rpy": optical,
        "left": left,
        "right": right,
        "imu": imu,
        "imu_rpy": imu_rpy,
        "resolution": (width, height),
        # MuJoCo's fovy is vertical: the horizontal fov at the block's own aspect.
        "fovy": math.degrees(2 * math.atan(math.tan(hfov / 2) / (width / height))),
    }


def mount_delta() -> tuple[np.ndarray, np.ndarray]:
    """``D = Rq``: the retired model's geoms were already in ``oakd_link``."""
    return quat_matrix(RETIRED_MOUNT_QUAT), np.zeros(3)


def mjcf(v: dict) -> str:
    half = [s / 2 for s in v["box_size"]]
    r_opt = rpy_matrix(v["optical_rpy"])  # rgb_camera_frame <- rgb_camera_optical_frame
    cam_x, cam_y = r_opt[:, 0], -r_opt[:, 1]
    front_x = v["box_pos"][0] + half[0] + 0.00035  # just proud of the box's front face
    w, h = v["resolution"]
    return f"""<mujoco model="oakd_pro">
  <!--
    Luxonis OAK-D Pro, mounted by `spawn_sensor` at the vendor joint origin of `<name>_link`. Written
    by external/convert/build_oakd_pro.py from turtlebot4_description/urdf/sensors/oakd.urdf.xacro
    @ turtlebot4 {TURTLEBOT4_COMMIT[:7]}; see OAKD_PRO_LICENSE.

    The `mount` body IS `oakd_link`: x forward (the lens normal), y left, z up. It carries the vendor
    inertial. There is no mesh (the vendor oakd_pro.dae is 12 MB / 152k triangles): the vendor
    collision box, at its vendor offset, is both what collides and what renders, and the front plate
    is a display cue on its lens face. `oakd_rgb` is the vendor `oakd_rgb_camera_optical_frame`
    turned into MuJoCo's camera convention (looks down -z, +y up); its fovy is the xacro Gazebo
    block's horizontal_fov re-expressed vertically at that block's {w}x{h}. The manifest's
    `frames:` publishes the vendor chain from this body.
  -->
  <compiler angle="radian" autolimits="true"/>

  <asset>
    <!-- The source DAE's own phong diffuse (0.19216 0.2039 0.2039): the device's dark grey shell. -->
    <material name="oakd_body" rgba="0.192 0.204 0.204 1" specular="0.4" shininess="0.3"/>
    <material name="oakd_glass" rgba="0.05 0.05 0.05 1" specular="0.6" shininess="0.6"/>
  </asset>

  <worldbody>
    <body name="mount">
      <inertial pos="0 0 0" mass="{fmt_num(v["mass"])}" diaginertia="{" ".join(f"{i:.9g}" for i in v["diaginertia"])}"/>
      <geom name="oakd_visual" type="box" pos="{fmt_vec(v["box_pos"])}" size="{fmt_vec(half)}"
            material="oakd_body"/>
      <geom name="oakd_front" type="box" pos="{fmt_num(front_x)} 0 {fmt_num(v["box_pos"][2])}"
            size="0.0004 0.045 0.008" material="oakd_glass" contype="0" conaffinity="0"/>
      <camera name="oakd_rgb" pos="{fmt_vec(v["rgb"])}" xyaxes="{fmt_vec(cam_x)} {fmt_vec(cam_y)}"
              fovy="{v["fovy"]:.2f}" resolution="{w} {h}"/>
    </body>
  </worldbody>
</mujoco>
"""


def frames_block(v: dict) -> str:
    opt = fmt_list(v["optical_rpy"])
    lines = [
        BEGIN,
        f"# ({XACRO.split('/', 1)[1]}). The macro's `name` param is the device name; the TurtleBot 4",
        "# instantiates it with its default, `oakd`.",
        "device_name: oakd",
        'frame_id: "{device_name}_rgb_camera_optical_frame"',
        "frames:",
        '  - {name: "{device_name}_link", parent: mount}',
        f'  - {{name: "{{device_name}}_rgb_camera_frame", parent: "{{device_name}}_link", '
        f"pos: {fmt_list(v['rgb'])}}}",
        f'  - {{name: "{{frame_id}}", parent: "{{device_name}}_rgb_camera_frame", rpy: {opt}}}',
    ]
    for side in ("left", "right"):
        lines += [
            f'  - {{name: "{{device_name}}_{side}_camera_frame", parent: "{{device_name}}_link", '
            f"pos: {fmt_list(v[side])}}}",
            f'  - {{name: "{{device_name}}_{side}_camera_optical_frame", '
            f'parent: "{{device_name}}_{side}_camera_frame", rpy: {opt}}}',
        ]
    lines += [
        f'  - {{name: "{{device_name}}_imu_frame", parent: "{{device_name}}_link", '
        f"pos: {fmt_list(v['imu'])}, rpy: {fmt_list(v['imu_rpy'])}}}",
        END,
    ]
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> None:
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--mount-delta", action="store_true", help="print the retired model's delta")
    ap.add_argument("--rewrite-mounts", nargs="+", type=Path, metavar="YAML")
    args = ap.parse_args(argv)
    deltas = {"oakd": ("oakd_pro", mount_delta())}
    if args.mount_delta:
        r, t = deltas["oakd"][1]
        print(
            f"oakd -> oakd_pro: T_new = T_old * D, D.pos = {fmt_list(t)}, "
            f"D.rpy = {fmt_list(matrix_rpy(r))}"
        )
        return
    if args.rewrite_mounts:
        for path in args.rewrite_mounts:
            print(f"{path}: {rewrite_mounts(path, deltas)} mount(s) re-expressed")
        return
    v = vendor()
    (MODEL / "oakd_pro.xml").write_text(mjcf(v))
    splice(MODEL / "oakd_pro.manifest.yaml", frames_block(v), BEGIN, END)
    print("oakd_pro: wrote oakd_pro.xml and the manifest's frames block")


if __name__ == "__main__":
    main()
